patches.text:
From: DBY-W09 kernel-port draft
Subject: [PATCH DRAFT] scsi: ufs: qcom: route SM8250 UFS OPP to RPMhPD

For an SM8250 UFS host with the supported two-domain topology, attach MMCX
as power-domains index 0 and keep GCC UFS_PHY_GDSC as index 1. The generic
device-core GenPD attach path intentionally skips consumers with multiple
power-domains, so the Qualcomm UFS probe owns the attach-list operation.

Before attaching the domains, validate every available UFS OPP entry:
each entry must have exactly one required-opps reference to the SM8250
RPMhPD provider's exact operating-points-v2 table. Then map required_dev
slot 0 to the MMCX virtual GenPD device before ufshcd_pltfrm_init() adds
the UFS OPP table.

The one-domain generic path is unchanged. Unsupported multi-domain
arrangements fail closed because the generic GenPD core skips them rather
than attaching any one of their domains. This defines the currently
supported two-domain contract for SM8250 UFS hosts; DBY-W09 is the board
currently adding this topology.

The code uses PD_FLAG_DEV_LINK_ON so the attached suppliers are
runtime-active while the UFS consumer is active. It deliberately does not
use PD_FLAG_REQUIRED_OPP, because this OPP table has one required-OPP slot,
not one slot for each attached domain.

This patch does not implement MMCX-to-MX parent propagation.
ROUND30 records this as a separate unresolved HOS4.3
corner-equivalence gate.

Draft only: not applied to a full kernel tree, compiled, checkpatched,
schema-validated or tested on hardware.

---
 drivers/ufs/host/ufs-qcom.c | 205 insertions(+)

diff --git a/drivers/ufs/host/ufs-qcom.c b/drivers/ufs/host/ufs-qcom.c
--- a/drivers/ufs/host/ufs-qcom.c
+++ b/drivers/ufs/host/ufs-qcom.c
@@ -11,12 +11,18 @@
 #include <linux/gpio/consumer.h>
 #include <linux/interconnect.h>
 #include <linux/module.h>
+#include <linux/errno.h>
 #include <linux/of.h>
 #include <linux/phy/phy.h>
 #include <linux/platform_device.h>
+#include <linux/pm_domain.h>
+#include <linux/pm_opp.h>
 #include <linux/reset-controller.h>
 #include <linux/time.h>
 #include <linux/unaligned.h>
 #include <linux/units.h>

+#include <dt-bindings/clock/qcom,gcc-sm8250.h>
+#include <dt-bindings/power/qcom,rpmhpd.h>
+
 #include <soc/qcom/ice.h>
@@ -2802,15 +2808,214 @@
 	.tx_eqtr_notify		= ufs_qcom_tx_eqtr_notify,
 };

+/*
+ * Validate one UFS OPP's required-opps reference against the SM8250 RPMhPD
+ * provider. The required OPP must belong to the provider's exact OPP table.
+ */
+static int ufs_qcom_validate_required_opp(struct device *dev,
+					  struct device_node *opp)
+{
+	struct device_node *req_opp_np, *req_table_np, *req_pd_np;
+	struct device_node *provider_table_np;
+	int num_required_opps, num_provider_tables, ret;
+
+	num_required_opps = of_count_phandle_with_args(opp, "required-opps",
+						       NULL);
+	if (num_required_opps != 1) {
+		ret = num_required_opps < 0 ? num_required_opps : -EINVAL;
+		return dev_err_probe(dev, ret,
+				     "expected one required-opps entry in %pOF\n",
+				     opp);
+	}
+
+	req_opp_np = of_parse_phandle(opp, "required-opps", 0);
+	if (!req_opp_np)
+		return dev_err_probe(dev, -EINVAL,
+				     "invalid required-opps target in %pOF\n",
+				     opp);
+
+	if (!of_device_is_available(req_opp_np)) {
+		ret = -EINVAL;
+		goto out_put_req_opp;
+	}
+
+	req_table_np = of_get_parent(req_opp_np);
+	if (!req_table_np) {
+		ret = -EINVAL;
+		goto out_put_req_opp;
+	}
+
+	req_pd_np = of_get_parent(req_table_np);
+	if (!req_pd_np) {
+		ret = -EINVAL;
+		goto out_put_req_table;
+	}
+
+	if (!of_device_is_compatible(req_table_np, "operating-points-v2") ||
+	    !of_device_is_compatible(req_pd_np, "qcom,sm8250-rpmhpd")) {
+		ret = -EINVAL;
+		goto out_put_req_pd;
+	}
+
+	/* The SM8250 RPMhPD provider must advertise exactly this one OPP table. */
+	num_provider_tables = of_count_phandle_with_args(req_pd_np,
+							 "operating-points-v2",
+							 NULL);
+	if (num_provider_tables != 1) {
+		ret = num_provider_tables < 0 ? num_provider_tables : -EINVAL;
+		goto out_put_req_pd;
+	}
+
+	provider_table_np = of_parse_phandle(req_pd_np,
+					     "operating-points-v2", 0);
+	if (!provider_table_np) {
+		ret = -EINVAL;
+		goto out_put_req_pd;
+	}
+
+	ret = provider_table_np == req_table_np ? 0 : -EINVAL;
+	of_node_put(provider_table_np);
+
+out_put_req_pd:
+	of_node_put(req_pd_np);
+out_put_req_table:
+	of_node_put(req_table_np);
+out_put_req_opp:
+	of_node_put(req_opp_np);
+
+	if (ret)
+		return dev_err_probe(dev, ret,
+				     "required-opps in %pOF is not from SM8250 RPMhPD table\n",
+				     opp);
+
+	return 0;
+}
+
+/*
+ * Check every available UFS OPP entry before configuring the required_dev
+ * mapping. This prevents a later-added OPP from bypassing the MMCX provider
+ * and table-identity checks.
+ */
+static int ufs_qcom_validate_opp_table(struct device *dev)
+{
+	struct device_node *opp_np, *opp;
+	unsigned int num_opps = 0;
+	int ret = 0;
+
+	opp_np = dev_pm_opp_of_get_opp_desc_node(dev);
+	if (!opp_np)
+		return dev_err_probe(dev, -ENODEV, "missing UFS OPP table\n");
+
+	for_each_available_child_of_node(opp_np, opp) {
+		ret = ufs_qcom_validate_required_opp(dev, opp);
+		if (ret) {
+			of_node_put(opp);
+			goto out_put_opp_table;
+		}
+
+		num_opps++;
+	}
+
+out_put_opp_table:
+	of_node_put(opp_np);
+	if (ret)
+		return ret;
+
+	if (!num_opps)
+		return dev_err_probe(dev, -EINVAL, "empty UFS OPP table\n");
+
+	return 0;
+}
+
+/*
+ * The supported SM8250 two-domain contract is MMCX first and GCC
+ * UFS_PHY_GDSC second. The one-domain generic path remains unchanged.
+ * Unknown two-domain layouts fail closed because the generic GenPD core
+ * deliberately skips automatic attachment for multi-domain consumers.
+ */
+static int ufs_qcom_attach_sm8250_domains(struct device *dev)
+{
+	struct dev_pm_domain_attach_data pd_data = {
+		.pd_flags = PD_FLAG_DEV_LINK_ON,
+	};
+	struct dev_pm_domain_list *pd_list;
+	struct dev_pm_opp_config opp_config = {};
+	struct of_phandle_args pd_args;
+	int num_domains, ret;
+
+	if (!dev->of_node ||
+	    !of_device_is_compatible(dev->of_node, "qcom,sm8250-ufshc"))
+		return 0;
+
+	num_domains = of_count_phandle_with_args(dev->of_node, "power-domains",
+						 "#power-domain-cells");
+	/* Preserve the existing generic one-domain path and no-domain case. */
+	if (num_domains == 1 || num_domains == -ENOENT)
+		return 0;
+
+	if (num_domains != 2)
+		return dev_err_probe(dev,
+				     num_domains < 0 ? num_domains : -EINVAL,
+				     "unsupported SM8250 UFS power-domain count\n");
+
+	/* The board DTS contract is MMCX index 0, GCC UFS_PHY_GDSC index 1. */
+	ret = of_parse_phandle_with_args(dev->of_node, "power-domains",
+					 "#power-domain-cells", 0, &pd_args);
+	if (ret)
+		return dev_err_probe(dev, ret, "failed to parse MMCX power domain\n");
+
+	if (!of_device_is_compatible(pd_args.np, "qcom,sm8250-rpmhpd") ||
+	    pd_args.args_count != 1 || pd_args.args[0] != RPMHPD_MMCX)
+		ret = -EINVAL;
+	of_node_put(pd_args.np);
+	if (ret)
+		return dev_err_probe(dev, ret, "first UFS domain is not RPMhPD MMCX\n");
+
+	ret = of_parse_phandle_with_args(dev->of_node, "power-domains",
+					 "#power-domain-cells", 1, &pd_args);
+	if (ret)
+		return dev_err_probe(dev, ret, "failed to parse UFS PHY power domain\n");
+
+	if (!of_device_is_compatible(pd_args.np, "qcom,gcc-sm8250") ||
+	    pd_args.args_count != 1 || pd_args.args[0] != UFS_PHY_GDSC)
+		ret = -EINVAL;
+	of_node_put(pd_args.np);
+	if (ret)
+		return dev_err_probe(dev, ret, "second UFS domain is not UFS_PHY_GDSC\n");
+
+	ret = ufs_qcom_validate_opp_table(dev);
+	if (ret)
+		return ret;
+
+	ret = devm_pm_domain_attach_list(dev, &pd_data, &pd_list);
+	if (ret < 0)
+		return dev_err_probe(dev, ret, "failed to attach UFS power domains\n");
+	if (ret != 2)
+		return dev_err_probe(dev, -EINVAL, "unexpected attached power-domain count\n");
+
+	opp_config.required_dev = pd_list->pd_devs[0];
+	opp_config.required_dev_index = 0;
+
+	ret = devm_pm_opp_set_config(dev, &opp_config);
+	if (ret)
+		return dev_err_probe(dev, ret, "failed to map UFS OPP to MMCX\n");
+
+	return 0;
+}
+
 /**
  * ufs_qcom_probe - probe routine of the driver
  * @pdev: pointer to Platform device handle
  *
  * Return: zero for success and non-zero for failure.
  */
 static int ufs_qcom_probe(struct platform_device *pdev)
 {
 	int err;
 	struct device *dev = &pdev->dev;

+	err = ufs_qcom_attach_sm8250_domains(dev);
+	if (err)
+		return err;
+
 	/* Perform generic probe */
--

From: DBY-W09 kernel-port draft
Subject: [PATCH DRAFT] scsi: ufs: qcom: manage SM8250 VDDP REF_CLK supply

Use qcom,vddp-ref-clk-supply to acquire the UFS device REF_CLK pad supply,
submit its configured load, and enable it before the Qualcomm PHY
is powered up. Keep it enabled for the initial storage-first milestone;
do not add suspend/resume rail switching yet.

Register a devm cleanup action after the managed regulator get. On device
unbind, driver-core devres release occurs after the UFS remove callback has
completed generic VCCQ shutdown. This action disables VDDP and then clears
its load before the managed regulator handle is put. It also handles failed
variant initialization after the generic HBA unwind.

Intentionally do not acquire qcom,vccq-parent-supply: ROUND14/51
establishes that ACK S8 load-only is a no-op and no enable owner is proven.
S8 is not enabled or mode-switched by this patch.

Prerequisites: apply ROUND32 and ROUND36 schema drafts, ROUND37 board DTS
delta, then ROUND33 dual-GenPD UFS driver draft before this patch.
The driver include hunk is written against the post-ROUND33 include list.

Draft only: not applied to a full tree, checkpatched, compiled, or tested.

---
 drivers/ufs/host/ufs-qcom.c | 76 ++++++++++++++++++++++++++++++++++++++++++++++++
 drivers/ufs/host/ufs-qcom.h | 4 ++++
 2 files changed, 80 insertions(+)

diff --git a/drivers/ufs/host/ufs-qcom.h b/drivers/ufs/host/ufs-qcom.h
--- a/drivers/ufs/host/ufs-qcom.h
+++ b/drivers/ufs/host/ufs-qcom.h
@@ -316,9 +316,13 @@
 struct gpio_desc;
+struct regulator;

 struct ufs_qcom_host {
 	struct phy *generic_phy;
 	struct ufs_hba *hba;
+	struct regulator *vddp_ref_clk;
+	bool vddp_ref_clk_load_set;
+	bool vddp_ref_clk_enabled;
 	struct ufs_pa_layer_attr dev_req_params;
 	struct clk_bulk_data *clks;
 	u32 num_clks;
 	bool is_lane_clks_enabled;

diff --git a/drivers/ufs/host/ufs-qcom.c b/drivers/ufs/host/ufs-qcom.c
--- a/drivers/ufs/host/ufs-qcom.c
+++ b/drivers/ufs/host/ufs-qcom.c
@@ -17,4 +17,5 @@
 #include <linux/platform_device.h>
 #include <linux/pm_domain.h>
 #include <linux/pm_opp.h>
+#include <linux/regulator/consumer.h>
 #include <linux/reset-controller.h>
@@ -1497,6 +1498,77 @@
 	return 0;
 }

+static void ufs_qcom_vddp_ref_clk_cleanup(void *data)
+{
+	struct ufs_qcom_host *host = data;
+	struct device *dev = host->hba->dev;
+	int ret;
+
+	if (host->vddp_ref_clk_enabled) {
+		ret = regulator_disable(host->vddp_ref_clk);
+		if (ret) {
+			dev_err(dev, "failed to disable VDDP REF_CLK supply: %d\n", ret);
+			return;
+		}
+		host->vddp_ref_clk_enabled = false;
+	}
+
+	if (host->vddp_ref_clk_load_set) {
+		ret = regulator_set_load(host->vddp_ref_clk, 0);
+		if (ret)
+			dev_err(dev, "failed to clear VDDP REF_CLK load: %d\n", ret);
+		else
+			host->vddp_ref_clk_load_set = false;
+	}
+}
+
+static int ufs_qcom_init_vddp_ref_clk(struct ufs_qcom_host *host)
+{
+	struct device *dev = host->hba->dev;
+	u32 load_uA;
+	int ret;
+
+	if (!dev->of_node ||
+	    !of_device_is_compatible(dev->of_node, "qcom,sm8250-ufshc") ||
+	    !of_find_property(dev->of_node, "qcom,vddp-ref-clk-supply", NULL))
+		return 0;
+
+	ret = of_property_read_u32(dev->of_node,
+				   "qcom,vddp-ref-clk-max-microamp", &load_uA);
+	if (ret)
+		return dev_err_probe(dev, ret, "missing VDDP REF_CLK load\n");
+	if (!load_uA)
+		return dev_err_probe(dev, -EINVAL, "invalid zero VDDP REF_CLK load\n");
+
+	host->vddp_ref_clk = devm_regulator_get(dev,
+						"qcom,vddp-ref-clk");
+	if (IS_ERR(host->vddp_ref_clk))
+		return dev_err_probe(dev, PTR_ERR(host->vddp_ref_clk),
+				     "failed to get VDDP REF_CLK supply\n");
+
+	/*
+	 * Register after the managed regulator get. The action runs before
+	 * regulator_put() and after ufshcd_remove() has shut down generic VCCQ.
+	 * ufshcd_alloc_host() and this variant's devm_kzalloc() registered their
+	 * release actions earlier; devres LIFO keeps hba and host alive here.
+	 */
+	ret = devm_add_action_or_reset(dev, ufs_qcom_vddp_ref_clk_cleanup, host);
+	if (ret)
+		return dev_err_probe(dev, ret, "failed to register VDDP cleanup\n");
+
+	ret = regulator_set_load(host->vddp_ref_clk, load_uA);
+	if (ret)
+		return dev_err_probe(dev, ret, "failed to set VDDP REF_CLK load\n");
+	host->vddp_ref_clk_load_set = true;
+
+	ret = regulator_enable(host->vddp_ref_clk);
+	if (ret)
+		return dev_err_probe(dev, ret, "failed to enable VDDP REF_CLK supply\n");
+	host->vddp_ref_clk_enabled = true;
+
+	return 0;
+}
+
 /**
  * ufs_qcom_init - bind phy with controller
  * @hba: host controller instance
@@ -1584,5 +1656,9 @@
 	err = ufs_qcom_ice_init(host);
 	if (err)
 		goto out_variant_clear;

+	err = ufs_qcom_init_vddp_ref_clk(host);
+	if (err)
+		goto out_variant_clear;
+
 	ufs_qcom_setup_clocks(hba, true, POST_CHANGE);
--

From: DBY-W09 Stage-A primary-source review
Subject: [PATCH DRAFT] phy: qcom-qmp-ufs: keep vdda-phy enabled when idle

The DBY-W09 HOS4.3 UFS PHY DTBO inventory records vdda-phy-always-on.
The downstream Qualcomm UFS PHY consumer semantics retain the vdda-phy
regulator enable while dropping its active load vote when the PHY is
off.

The ACK QMP UFS PHY driver currently bulk-disables every PHY regulator in
qmp_ufs_power_off(), ignoring this consumer property. Preserve the existing
bulk path for nodes without the property. When the property is present,
enable vdda-phy on first PHY power-on, keep that consumer enable balanced
across PHY power cycles while toggling its load between init_load_uA and
zero, continue to enable/disable the remaining PHY regulators normally,
and register a device-managed cleanup action to balance the retained enable
before the managed regulator handles are released.

The first configured regulator must remain vdda-phy, as in the current
Qualcomm UFS PHY regulator lists. Reject an unexpected list rather than
silently applying the special case to the wrong rail.

Candidate implementation only; no regulator hardware test or device boot
has run. Immutable source revision and blob identity are recorded in the
ROUND61 ROUND63 integration report.

---
 drivers/phy/qualcomm/phy-qcom-qmp-ufs.c | candidate
diff --git a/drivers/phy/qualcomm/phy-qcom-qmp-ufs.c b/drivers/phy/qualcomm/phy-qcom-qmp-ufs.c
--- a/drivers/phy/qualcomm/phy-qcom-qmp-ufs.c
+++ b/drivers/phy/qualcomm/phy-qcom-qmp-ufs.c
@@ -15,7 +15,8 @@
 #include <linux/of_address.h>
 #include <linux/phy/phy.h>
 #include <linux/platform_device.h>
 #include <linux/regulator/consumer.h>
 #include <linux/reset.h>
 #include <linux/slab.h>
+#include <linux/string.h>

@@ -1133,6 +1134,8 @@
 	struct clk_bulk_data *clks;
 	int num_clks;
 	struct regulator_bulk_data *vregs;
+	bool vdda_phy_always_on;
+	bool vdda_phy_enabled;
 	struct reset_control *ufs_reset;

 	struct phy *phy;
@@ -1829,31 +1832,123 @@
 		qmp_ufs_init_all(qmp, &cfg->tbls_hs_b);
 }

+static void qmp_ufs_vdda_phy_cleanup(void *data)
+{
+	struct qmp_ufs *qmp = data;
+	int ret;
+
+	if (!qmp->vdda_phy_enabled)
+		return;
+
+	ret = regulator_set_load(qmp->vregs[0].consumer, 0);
+	if (ret < 0)
+		dev_err(qmp->dev, "failed to clear vdda-phy load, err=%d\n", ret);
+
+	ret = regulator_disable(qmp->vregs[0].consumer);
+	if (ret)
+		dev_err(qmp->dev, "failed to disable vdda-phy, err=%d\n", ret);
+
+	qmp->vdda_phy_enabled = false;
+}
+
+static int qmp_ufs_regulators_enable(struct qmp_ufs *qmp)
+{
+	const struct qmp_phy_cfg *cfg = qmp->cfg;
+	int cleanup_ret;
+	int ret;
+
+	if (!qmp->vdda_phy_always_on)
+		return regulator_bulk_enable(cfg->num_vregs, qmp->vregs);
+
+	/* The SM8250 UFS PHY list orders vdda-phy before vdda-pll. */
+	if (cfg->num_vregs < 2 ||
+	    strcmp(cfg->vreg_list[0].supply, "vdda-phy"))
+		return -EINVAL;
+
+	ret = regulator_set_load(qmp->vregs[0].consumer,
+				 qmp->vregs[0].init_load_uA);
+	if (ret < 0)
+		return ret;
+
+	if (!qmp->vdda_phy_enabled) {
+		ret = regulator_enable(qmp->vregs[0].consumer);
+		if (ret)
+			goto err_clear_load;
+		qmp->vdda_phy_enabled = true;
+	}
+
+	/* Keep vdda-phy enabled across PHY power-off; toggle vdda-pll normally. */
+	ret = regulator_bulk_enable(cfg->num_vregs - 1, &qmp->vregs[1]);
+	if (ret)
+		goto err_clear_load;
+
+	return 0;
+
+err_clear_load:
+	cleanup_ret = regulator_set_load(qmp->vregs[0].consumer, 0);
+	if (cleanup_ret < 0)
+		dev_err(qmp->dev, "failed to clear vdda-phy load after error, err=%d\n",
+			cleanup_ret);
+	return ret;
+}
+
+static int qmp_ufs_regulators_disable(struct qmp_ufs *qmp)
+{
+	const struct qmp_phy_cfg *cfg = qmp->cfg;
+	int load_ret;
+	int ret;
+
+	if (!qmp->vdda_phy_always_on)
+		return regulator_bulk_disable(cfg->num_vregs, qmp->vregs);
+
+	if (cfg->num_vregs < 2 ||
+	    strcmp(cfg->vreg_list[0].supply, "vdda-phy"))
+		return -EINVAL;
+
+	ret = regulator_bulk_disable(cfg->num_vregs - 1, &qmp->vregs[1]);
+	if (!qmp->vdda_phy_enabled)
+		return ret;
+
+	/* Drop the active load vote but retain the vdda-phy enable reference. */
+	load_ret = regulator_set_load(qmp->vregs[0].consumer, 0);
+	if (load_ret < 0) {
+		dev_err(qmp->dev, "failed to clear vdda-phy load, err=%d\n",
+			load_ret);
+		if (!ret)
+			ret = load_ret;
+	}
+
+	return ret;
+}
+
-static int qmp_ufs_power_on(struct phy *phy)
-{
-	struct qmp_ufs *qmp = phy_get_drvdata(phy);
-	const struct qmp_phy_cfg *cfg = qmp->cfg;
-	void __iomem *pcs = qmp->pcs;
-	int ret;
-
-	ret = regulator_bulk_enable(cfg->num_vregs, qmp->vregs);
-	if (ret) {
-		dev_err(qmp->dev, "failed to enable regulators, err=%d\n", ret);
-		return ret;
-	}
-
-	ret = clk_bulk_prepare_enable(qmp->num_clks, qmp->clks);
-	if (ret)
-		goto err_disable_regulators;
-
-	qphy_setbits(pcs, cfg->regs[QPHY_PCS_POWER_DOWN_CONTROL], SW_PWRDN);
-	return 0;
-
-err_disable_regulators:
-	regulator_bulk_disable(cfg->num_vregs, qmp->vregs);
-	return ret;
-}
-
+static int qmp_ufs_power_on(struct phy *phy)
+{
+	struct qmp_ufs *qmp = phy_get_drvdata(phy);
+	const struct qmp_phy_cfg *cfg = qmp->cfg;
+	void __iomem *pcs = qmp->pcs;
+	int disable_ret;
+	int ret;
+
+	ret = qmp_ufs_regulators_enable(qmp);
+	if (ret) {
+		dev_err(qmp->dev, "failed to enable regulators, err=%d\n", ret);
+		return ret;
+	}
+
+	ret = clk_bulk_prepare_enable(qmp->num_clks, qmp->clks);
+	if (ret)
+		goto err_disable_regulators;
+
+	qphy_setbits(pcs, cfg->regs[QPHY_PCS_POWER_DOWN_CONTROL], SW_PWRDN);
+	return 0;
+
+err_disable_regulators:
